t.script:
(function () {
    var btn = document.getElementById('wa_enrol');
    if (!btn) { return; }
    var statusEl = document.getElementById('wa_status');

    function b64urlToBuf(value) {
        var padded = value.replace(/-/g, '+').replace(/_/g, '/');
        while (padded.length % 4) { padded += '='; }
        var raw = atob(padded);
        var buf = new Uint8Array(raw.length);
        for (var i = 0; i < raw.length; i++) { buf[i] = raw.charCodeAt(i); }
        return buf.buffer;
    }
    function bufToB64url(buf) {
        var bytes = new Uint8Array(buf), str = '';
        for (var i = 0; i < bytes.length; i++) { str += String.fromCharCode(bytes[i]); }
        return btoa(str).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
    }
    function rpc(url, params) {
        return fetch(url, {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({jsonrpc: '2.0', method: 'call', params: params || {}})
        }).then(function (r) { return r.json(); }).then(function (payload) {
            if (payload.error) { throw new Error(payload.error.data
                ? payload.error.data.message : payload.error.message); }
            return payload.result;
        });
    }

    btn.addEventListener('click', function () {
        statusEl.textContent = 'Waiting for your device…';
        if (!window.PublicKeyCredential) {
            statusEl.textContent = 'This browser does not support WebAuthn.';
            return;
        }
        rpc('/webauthn/register/options').then(function (options) {
            options.challenge = b64urlToBuf(options.challenge);
            options.user.id = new TextEncoder().encode(options.user.id);
            (options.excludeCredentials || []).forEach(function (c) {
                c.id = b64urlToBuf(c.id);
            });
            return navigator.credentials.create({publicKey: options});
        }).then(function (credential) {
            return rpc('/webauthn/register/verify', {
                device_label: document.getElementById('wa_label').value,
                credential: {
                    id: credential.id,
                    rawId: bufToB64url(credential.rawId),
                    type: credential.type,
                    response: {
                        clientDataJSON: bufToB64url(credential.response.clientDataJSON),
                        attestationObject: bufToB64url(credential.response.attestationObject)
                    },
                    transports: credential.response.getTransports
                        ? credential.response.getTransports() : []
                }
            });
        }).then(function (result) {
            if (result && result.ok) {
                statusEl.textContent = 'Device enrolled.';
                window.location.reload();
            } else {
                statusEl.textContent = (result && result.error) || 'Enrolment failed.';
            }
        }).catch(function (err) {
            statusEl.textContent = 'Enrolment failed: ' + err.message;
        });
    });
})();
